units=[];lesson_records=[]
for u in d['units']:
    need,core,extension,model,evidence,finding=specs[u['id']]
    units.append(dict(unitId=u['id'],title=u['title'],realNeed=need,core=core,extension=extension,model=model,evidence=evidence,reviewFinding=finding))
for l in d['lessons']:
    altered=[q for q in l['practice'] if q['id'] in changed]
    retained_slot=7 if l['id'] in ['G3-U02-E02','G3-U03-B01'] else 5
    advanced=altered or [l['practice'][retained_slot]]
    cards=[q['id'] for q in b['tasks'] if q['parentLessonId']==l['id']]
    record=dict(lessonId=l['id'],unitId=l['unitId'],title=l['title'],realProblem=l['realProblem'],coreObjective=l['objective'],
        coreExitTaskIds=l['teachingContract']['minimumTaskIds'],extensionTaskIds=[q['id'] for q in advanced],
        extensionEvidence=[q.get('thinkingDemand',q['reason']) for q in advanced],optionalThinkingTaskIds=cards,
        reviewTaskIds=[q['id'] for q in l['practice'][8:]],
        decision='revised_elective' if altered else 'retained_after_structure_review',
        evidenceBoundary='P09–P12用于本课原有目标的分日回顾，不因基础回顾通过就判新提升已掌握。看过答案的原题不再作为独立证据；后续选同方法、条件有变化的题单独记录，暂无对应独立题时标待迁移。')
    lesson_records.append(record)
    l['extensionContract']={k:record[k] for k in ['extensionTaskIds','extensionEvidence','optionalThinkingTaskIds','evidenceBoundary']}
    l['extensionContract']['selectionRule']='基础过关后，本课提升与关联思维卡合计最多选一道；需要多个任务才讲清的可分次，允许跳过提升继续教材主线。'
quality=dict(version='g3-quality-20260925.1',scope='grade3-only',basis='逐课核查60课的现实问题、为什么、P05–P08及全部60张关联思维卡；基础题和分日题保留原审核记录，不声称本轮从零重新证明720题。',
    standards=['课本基础目标完整而可独立通过','提升必须增加实质思考，不以题长和数字大小充数','明确所求量、前后时点、整体、可操作条件与边界','图/表/实物模型按问题选，不强制每题画几何图','答案含推理、可接受的不同表示、反例或解集边界','基础与提升分开记录掌握证据，重复原题不冒充迁移'],
    units=units,lessons=lesson_records)
(BASE/'grade-3-quality-map.json').write_text(json.dumps(quality,ensure_ascii=False,indent=2)+'\n')
(BASE/'grade-3.json').write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
lines=['# Kevin三年级：全单元内容质量复查与改写记录','','2026-09-25。目标是把“基础知识 → 关系或条件发生变化 → 数学思想”的要求用于全年，而不只补一个长度专题。四至六年级保持冻结。','','## 本轮做了什么','','逐课检查60课的现实任务、原因说明、P05–P08，以及全部60张思维卡。48课各替换1道偏浅或重复的备选练习，另12课保留已有合格对照、反例或边界题。题总数不增长：仍60课720道课内/回顾任务，另60张思维卡与6道专用检查，共786个任务。11幅新课内图加此前15幅思维图，共26幅。','','没有把所有基础题改成奥数题：每课基本目标与最低过关题不变，48道新题都在可选位置。基础、提升、独立迁移是不同证据。720道原题不宣称本轮从零重新语义证明；保留原审核记录，并重审本次改写与关联关系。','','## 全部17个教材入口逐项核查','','| 单元 | 现实需要与基础 | 提升新增的思考 | 模型与证据 | 本轮判断/修改 |','|---|---|---|---|']
for u in units:lines.append('| '+' | '.join([u['unitId']+' '+u['title'],u['realNeed']+'；基础：'+u['core'],u['extension'],u['model']+'；'+u['evidence'],u['reviewFinding']])+' |')
lines+=['','## 全部60课的具体入口','','每行指向已经写入完整教案的实际题目，不是将来才准备的题目名称。选学题与思维卡每次合计最多选一道；“保留”表示已检查结构而非漏改。','','| 课程 | 本课提升题 | 需要观察的思考 | 处理 |','|---|---|---|---|']
for r in lesson_records:lines.append('| '+' | '.join([r['lessonId']+' '+r['title'],'、'.join(r['extensionTaskIds']),'；'.join(r['extensionEvidence']),'已改写' if r['decision']=='revised_elective' else '保留合格题'])+' |')
lines+=['','## 48题逐题改写记录','','这里只展示原题与新题的差别；答案、理由和配图的权威版本见完整教案。']
for c in changes:
    lines+=['',f'### {c["taskId"]}','','**原来：**'+c['before']['question'],'','**现在：**'+c['after']['question'],'','**参考：**'+c['after']['answer'],'','**增加的思考：**'+c['thinking']]
lines+=['','## 后续实现的统一规则','','1. 进入课本章节先显示基础任务，过关后可选本课延伸或同方法卡。不得再次创建重复课程或重复奖励。','2. 改变条件时明确告诉Kevin改了哪一点：位置、整体、份数、允许操作、信息充分性或问题目标。不能只悄悄换数字。','3. 题目需要的图默认可见；提示性的图默认收起。例如共线点的两种位置是要孩子构造的，不能一开始就把两种答案模型亮出来。','4. 解释可以画、摆、说或列式；不能只做“能/不能”的选择就判掌握，更不能只用参考文字逐字匹配。','5. 每天最多一道提升/奥数，复杂任务可跨日。原有分日复习针对原目标；提升需单独记录是否独立、用过哪级提示、能否迁移，证据不足就标待迁移。','6. 先实现并试学代表模型，再推广渲染器；图文审阅文件可离线读，但不代表网站已接入或互动已验收。','']
(OUT/'Kevin三年级_全单元质量复查与改写记录.md').write_text('\n'.join(lines))
print('Mapped',len(units),'units /',len(lesson_records),'lessons to actual extension tasks.')
